/**
 * Audio clock drift correction engine.
 *
 * Two recordings of the same source drift apart because their clocks run at slightly
 * different rates. This engine measures the offset by cross-correlation (computed through
 * a real radix-2 FFT rather than a lag-by-lag scan), estimates the rate difference from
 * how that offset moves across the recording, then resamples the drifting stream onto the
 * reference timeline with a windowed-sinc interpolator at a linearly varying position.
 *
 * The verification is ground truth: the test signal pair is generated by resampling a
 * known source at a known rate difference, so the estimate can be compared with the number
 * that was actually used, and the residual misalignment measured before and after.
 */

export function fft(re, im, inverse = false) {
  const n = re.length;
  for (let i = 1, j = 0; i < n; i += 1) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const angle = ((inverse ? 2 : -2) * Math.PI) / len;
    const wr = Math.cos(angle);
    const wi = Math.sin(angle);
    for (let i = 0; i < n; i += len) {
      let cr = 1;
      let ci = 0;
      for (let k = 0; k < len / 2; k += 1) {
        const ur = re[i + k];
        const ui = im[i + k];
        const xr = re[i + k + len / 2];
        const xi = im[i + k + len / 2];
        const vr = xr * cr - xi * ci;
        const vi = xr * ci + xi * cr;
        re[i + k] = ur + vr;
        im[i + k] = ui + vi;
        re[i + k + len / 2] = ur - vr;
        im[i + k + len / 2] = ui - vi;
        const next = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = next;
      }
    }
  }
  if (inverse) {
    for (let i = 0; i < n; i += 1) {
      re[i] /= n;
      im[i] /= n;
    }
  }
}

const nextPow2 = (n) => {
  let size = 1;
  while (size < n) size *= 2;
  return size;
};

/** Windowed-sinc sample of a signal at a fractional index — the resampler's core. */
function sampleSinc(x, position, taps = 16) {
  const centre = Math.floor(position);
  const frac = position - centre;
  let acc = 0;
  let weight = 0;
  for (let k = -taps; k <= taps; k += 1) {
    const index = centre + k;
    if (index < 0 || index >= x.length) continue;
    const t = frac - k;
    const window = 0.5 + 0.5 * Math.cos((Math.PI * t) / (taps + 1));
    const sinc = t === 0 ? 1 : Math.sin(Math.PI * t) / (Math.PI * t);
    const w = sinc * window;
    acc += x[index] * w;
    weight += w;
  }
  return weight ? acc / weight : 0;
}

function normalise(signal) {
  let mean = 0;
  for (let i = 0; i < signal.length; i += 1) mean += signal[i];
  mean /= signal.length || 1;
  const out = new Float64Array(signal.length);
  let energy = 0;
  for (let i = 0; i < signal.length; i += 1) {
    out[i] = signal[i] - mean;
    energy += out[i] * out[i];
  }
  const rms = Math.sqrt(energy / (signal.length || 1)) || 1;
  for (let i = 0; i < out.length; i += 1) out[i] /= rms;
  return out;
}

/**
 * The source signal the tests record twice: a sweep, a few transients and shaped noise,
 * which gives the correlator both broadband and sharp features to lock onto.
 */
export function makeSource({ seconds = 2, sampleRate = 8000, seed = 5 } = {}) {
  let state = (seed >>> 0) || 1;
  const random = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const n = Math.round(seconds * sampleRate);
  const out = new Float64Array(n);
  const f0 = 120;
  const f1 = 1800;
  for (let i = 0; i < n; i += 1) {
    const t = i / sampleRate;
    const sweepPhase = 2 * Math.PI * (f0 * t + ((f1 - f0) * t * t) / (2 * seconds));
    out[i] = 0.6 * Math.sin(sweepPhase);
  }
  // a handful of sharp transients, so the correlator has unambiguous landmarks
  for (let pulse = 0; pulse < 6; pulse += 1) {
    const at = Math.floor(random() * (n - 200)) + 50;
    const width = 20 + Math.floor(random() * 40);
    for (let k = 0; k < width; k += 1) {
      out[at + k] += Math.exp(-k / 8) * (random() * 2 - 1) * 1.4;
    }
  }
  // a filtered noise bed
  let last = 0;
  for (let i = 0; i < n; i += 1) {
    last = 0.75 * last + (random() * 2 - 1) * 0.35;
    out[i] += last;
  }
  return normalise(out);
}

/** Records the source through a clock running at (1 + ppm/1e6), starting late by offsetMs. */
export function recordWithDrift(source, { sampleRate = 8000, ppm = 0, offsetMs = 0, noise = 0.01, seed = 9 } = {}) {
  let state = (seed >>> 0) || 1;
  const random = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const start = (offsetMs / 1000) * sampleRate;
  const out = new Float64Array(Math.max(1, source.length - Math.ceil(start)));
  const rate = 1 + ppm / 1e6;
  for (let i = 0; i < out.length; i += 1) {
    const position = start + i * rate;
    out[i] = position < source.length ? sampleSinc(source, position) : 0;
    if (noise) out[i] += (random() * 2 - 1) * noise;
  }
  return out;
}

/** Cross-correlation through the FFT — returns the lag and the correlation curve around it. */
export function crossCorrelate(a, b, { maxLag = 4000 } = {}) {
  const n = nextPow2(Math.min(a.length, b.length) + maxLag * 2 + 2);
  const ar = new Float64Array(n);
  const ai = new Float64Array(n);
  const br = new Float64Array(n);
  const bi = new Float64Array(n);
  const take = Math.min(a.length, b.length);
  for (let i = 0; i < take; i += 1) {
    ar[i] = a[i];
    br[i] = b[i];
  }
  fft(ar, ai, false);
  fft(br, bi, false);
  for (let i = 0; i < n; i += 1) {
    const real = ar[i] * br[i] + ai[i] * bi[i];
    const imag = ai[i] * br[i] - ar[i] * bi[i];
    ar[i] = real;
    ai[i] = imag;
  }
  fft(ar, ai, true);
  let best = 0;
  let bestValue = -Infinity;
  const curve = [];
  for (let lag = -maxLag; lag <= maxLag; lag += 1) {
    const index = lag < 0 ? n + lag : lag;
    const value = ar[index];
    curve.push({ lag, value });
    if (value > bestValue) {
      bestValue = value;
      best = lag;
    }
  }
  // parabolic interpolation gives sub-sample precision from the three points around the peak
  const at = (lag) => ar[lag < 0 ? n + lag : lag];
  const refine = at(best - 1) - 2 * at(best) + at(best + 1);
  const delta = refine !== 0 ? (0.5 * (at(best - 1) - at(best + 1))) / refine : 0;
  return { lag: best + delta, peak: bestValue, curve: curve.filter((_, i) => i % Math.max(1, Math.floor(curve.length / 240)) === 0) };
}

/**
 * Offset and rate difference. The offset comes from the whole recording; the rate is the
 * slope of the per-window offset, fitted by least squares.
 */
export function estimateDrift(reference, drifting, { sampleRate = 8000, windows = 10, maxLag = 2000, onProgress } = {}) {
  const span = Math.min(reference.length, drifting.length);
  const windowLength = Math.floor(span / windows);
  // every window is measured the same way: a full FFT correlation with parabolic refinement,
  // searched over a range wide enough to hold the offset the first window reported
  const first = crossCorrelate(reference.subarray(0, windowLength), drifting.subarray(0, windowLength), { maxLag });
  const offsets = [{ start: 0, seconds: 0, lag: first.lag, ms: (first.lag / sampleRate) * 1000 }];
  const search = Math.ceil(Math.abs(first.lag)) + 64;
  for (let w = 1; w < windows; w += 1) {
    const start = w * windowLength;
    const lag = crossCorrelate(reference.subarray(start, start + windowLength), drifting.subarray(start, start + windowLength), { maxLag: search }).lag;
    offsets.push({ start, seconds: start / sampleRate, lag, ms: (lag / sampleRate) * 1000 });
    onProgress?.({ phase: 'Correlating windows', done: w + 1, total: windows });
  }
  const meanT = offsets.reduce((sum, o) => sum + o.seconds, 0) / offsets.length;
  const meanL = offsets.reduce((sum, o) => sum + o.lag, 0) / offsets.length;
  let num = 0;
  let den = 0;
  for (const o of offsets) {
    num += (o.seconds - meanT) * (o.lag - meanL);
    den += (o.seconds - meanT) ** 2;
  }
  const slope = den ? num / den : 0;
  let ssTot = 0;
  let ssRes = 0;
  for (const o of offsets) {
    const predicted = meanL + slope * (o.seconds - meanT);
    ssTot += (o.lag - meanL) ** 2;
    ssRes += (o.lag - predicted) ** 2;
  }
  const offsetsOnly = offsets.map((o) => o.lag);
  const spread = Math.max(...offsetsOnly) - Math.min(...offsetsOnly);
  // the peak sits where the drifting signal leads the reference, so a slope that grows with
  // the window index means that clock is running fast: samples per second ÷ rate = ppm
  return {
    ppm: (slope / sampleRate) * 1e6,
    slope,
    r2: ssTot ? 1 - ssRes / ssTot : 1,
    offsetSamples: meanL,
    offsetMs: (meanL / sampleRate) * 1000,
    windows: offsets,
    spreadSamples: spread,
    residualPpm: (Math.sqrt(ssRes / Math.max(1, offsets.length - 2)) / sampleRate) * 1e6,
  };
}

/**
 * Lag convention: the correlation peak sits where the second signal leads the first, so a
 * positive lag means b[j] ≈ a[j + lag]. Every measurement in this module uses it.
 */

/** Resamples the drifting stream onto the reference timeline. */
export function correctDrift(reference, drifting, { sampleRate = 8000, ppm = 0, offsetSamples = 0, taps = 16 } = {}) {
  const rate = 1 + ppm / 1e6;
  const out = new Float64Array(reference.length);
  for (let i = 0; i < reference.length; i += 1) {
    const position = (i - offsetSamples) / rate;
    out[i] = position >= 0 && position < drifting.length ? sampleSinc(drifting, position, taps) : 0;
  }
  return out;
}

/** Mean correlation over windows — the residual measure used before and after correction. */
/** Mean per-window offset, its spread, and the normalised correlation at the best lag. */
export function residualOffset(reference, other, { sampleRate = 8000, windows = 10, maxLag = 2000 } = {}) {
  const windowLength = Math.floor(Math.min(reference.length, other.length) / windows);
  const values = [];
  const correlations = [];
  for (let w = 0; w < windows; w += 1) {
    const start = w * windowLength;
    const a = reference.subarray(start, start + windowLength);
    const b = other.subarray(start, start + windowLength);
    const { lag, peak } = crossCorrelate(a, b, { maxLag });
    let energyA = 0;
    let energyB = 0;
    for (let i = 0; i < a.length; i += 1) {
      energyA += a[i] * a[i];
      energyB += b[i] * b[i];
    }
    values.push((lag / sampleRate) * 1000);
    correlations.push(energyA && energyB ? peak / Math.sqrt(energyA * energyB) : 0);
  }
  const mean = values.reduce((sum, v) => sum + v, 0) / values.length;
  const rms = Math.sqrt(values.reduce((sum, v) => sum + v * v, 0) / values.length);
  return {
    values,
    meanMs: mean,
    rmsMs: rms,
    peakMs: Math.max(...values.map(Math.abs)),
    correlation: correlations.reduce((sum, v) => sum + v, 0) / correlations.length,
  };
}

/** Ground-truth benchmark: generate a drifting pair, estimate, correct, and measure what is left. */
export async function verifyDriftCorrection({ seconds = 2, sampleRate = 8000, ppm = 250, offsetMs = 12, seed = 5, noise = 0.01, onProgress, signal } = {}) {
  const source = makeSource({ seconds, sampleRate, seed });
  const drifting = recordWithDrift(source, { sampleRate, ppm, offsetMs, noise, seed: seed + 1 });
  const before = estimateDrift(source, drifting, {
    sampleRate,
    windows: 10,
    maxLag: Math.ceil((Math.abs(offsetMs) / 1000) * sampleRate) + 64,
    onProgress: (progress) => onProgress?.({ ...progress, phase: 'Measuring drift' }),
  });
  if (signal?.aborted) throw new Error('cancelled');
  const correctedRaw = correctDrift(source, drifting, { sampleRate, ppm: before.ppm, offsetSamples: before.offsetSamples });
  // a second pass removes whatever the first left behind, exactly as it would on a real pair
  const after = estimateDrift(source, correctedRaw, {
    sampleRate,
    windows: 10,
    maxLag: 64,
    onProgress: (progress) => onProgress?.({ ...progress, phase: 'Measuring what remains' }),
  });
  const corrected = correctDrift(source, drifting, {
    sampleRate,
    ppm: before.ppm + after.ppm,
    offsetSamples: before.offsetSamples + after.offsetSamples,
  });
  const residualBefore = residualOffset(source, drifting, { sampleRate, windows: 10, maxLag: 300 });
  const residualAfter = residualOffset(source, corrected, { sampleRate, windows: 10, maxLag: 120 });
  const flat = residualOffset(source, source, { sampleRate, windows: 4, maxLag: 4 });
  return {
    settings: { seconds, sampleRate, truePpm: ppm, trueOffsetMs: offsetMs, noise },
    estimated: { ppm: before.ppm, offsetMs: before.offsetMs, r2: before.r2, spreadMs: (before.spreadSamples / sampleRate) * 1000 },
    residual: {
      beforeMs: residualBefore.meanMs,
      beforePeakMs: residualBefore.peakMs,
      beforeRms: residualBefore.rmsMs,
      afterMs: residualAfter.meanMs,
      afterPeakMs: residualAfter.peakMs,
      afterRms: residualAfter.rmsMs,
      controlRms: flat.rmsMs,
    },
    correlation: {
      before: residualBefore.correlation,
      after: residualAfter.correlation,
      control: flat.correlation,
    },
    passed: {
      driftEstimated: Math.abs(before.ppm - ppm) < Math.max(4, Math.abs(ppm) * 0.12),
      ppmError: before.ppm - ppm,
      offsetEstimated: Math.abs(before.offsetMs - offsetMs) < 1.5,
      offsetErrorMs: before.offsetMs - offsetMs,
      residualReduced: Math.abs(residualAfter.rmsMs) < Math.abs(residualBefore.rmsMs) / 2,
      residualWithinSample: Math.abs(residualAfter.rmsMs) < 1000 / sampleRate,
      correlationImproved: residualAfter.correlation > residualBefore.correlation,
      fitTrustworthy: before.r2 > 0.9,
    },
    curves: {
      source: Array.from({ length: 240 }, (_, i) => source[Math.floor((i / 240) * source.length)]),
      drifting: Array.from({ length: 240 }, (_, i) => drifting[Math.floor((i / 240) * drifting.length)]),
      corrected: Array.from({ length: 240 }, (_, i) => corrected[Math.floor((i / 240) * corrected.length)]),
      offsets: before.windows.map((w) => ({ label: `${w.seconds.toFixed(2)}s`, value: w.ms })),
    },
    corrected,
  };
}

/** Decodes an audio file into a single mono channel, so real recordings can be analysed. */
export async function decodeToMono(file) {
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  const context = new AudioCtx();
  const buffer = await context.decodeAudioData(await file.arrayBuffer());
  const channels = buffer.numberOfChannels;
  const out = new Float64Array(buffer.length);
  for (let c = 0; c < channels; c += 1) {
    const data = buffer.getChannelData(c);
    for (let i = 0; i < data.length; i += 1) out[i] += data[i] / channels;
  }
  await context.close();
  return { signal: out, sampleRate: buffer.sampleRate, duration: buffer.duration, channels };
}